<template>
  <el-dialog
    title="申请企业认证"
    :visible.sync="dialogFormVisible"
    :destroy-on-close="true"
    width="780px"
    top="60px"
    center
  >
    <div
      class="check-status-box"
      v-if="companyInfo && companyInfo.status == -1"
    >
      <el-tag type="danger">未通过</el-tag>
    </div>
    <el-form :model="form" :rules="rules" ref="companyForm">
      <div class="form-group">
        <el-form-item prop="name" label="企业名称">
          <el-input
            v-model="form.name"
            autocomplete="off"
            maxlength="100"
            show-word-limit
            :readonly="companyInfo && companyInfo.info == 1"
          ></el-input>
        </el-form-item>
        <el-form-item prop="code" label="信用代码">
          <el-input
            v-model="form.code"
            autocomplete="off"
            placeholder="信用代码"
            :readonly="companyInfo && companyInfo.info == 1"
          ></el-input>
        </el-form-item>
      </div>
      <div class="form-group">
        <el-form-item prop="contactName" label="联系人">
          <el-input
            v-model="form.contactName"
            autocomplete="off"
            placeholder="联系人"
            :readonly="companyInfo && companyInfo.info == 1"
          ></el-input>
        </el-form-item>
        <el-form-item prop="contactMobile" label="联系人手机">
          <el-input
            v-model="form.contactMobile"
            autocomplete="off"
            placeholder="联系人手机"
            :readonly="companyInfo && companyInfo.info == 1"
          ></el-input>
        </el-form-item>
      </div>
      <div class="form-group">
        <el-form-item prop="contactEmail" label="联系人邮箱" class="mb12">
          <el-input
            v-model="form.contactEmail"
            autocomplete="off"
            placeholder="联系人邮箱"
            :readonly="companyInfo && companyInfo.info == 1"
          ></el-input>
        </el-form-item>
        <el-form-item label="企业Logo" class="mb12">
          <vr-upload
            key="logo"
            ref="logoUpload"
            uploadClass="logo-container"
            tip="建议尺寸：120*60"
            listType
            :cropImg="false"
            :autoUpload="true"
            :autoCropWidth="120"
            :autoCropHeight="60"
            :cropDialogModalAppendToBody="false"
            :cropDialogAppendToBody="true"
            :cropDialogDestroyOnClose="true"
            cropDialogWidth="800px"
            cropDialogTop="8vh"
            :fileList="[
              {
                name: form.name,
                url: form.logoFull,
                path: form.logo,
              },
            ]"
            @onSuccess="onLogoUploadSuccess"
          />
        </el-form-item>
      </div>
      <div class="form-group">
        <el-form-item label="营业执照">
          <vr-upload
            key="license"
            uploadClass="avatar-container"
            tip="建议大小：2MB以内"
            ref="licenseUpload"
            listType
            :cropImg="false"
            :autoUpload="true"
            :autoCropWidth="90"
            :autoCropHeight="90"
            :cropDialogModalAppendToBody="false"
            :cropDialogAppendToBody="true"
            :cropDialogDestroyOnClose="true"
            cropDialogWidth="800px"
            cropDialogTop="8vh"
            :fileList="[
              {
                name: form.name,
                url: form.licenseFull,
                path: form.license,
              },
            ]"
            @onSuccess="onLicenseUploadSuccess"
          />
        </el-form-item>
      </div>
    </el-form>
    <div slot="footer" class="dialog-footer">
      <el-button @click="cancel">取 消</el-button>
      <el-button
        type="primary"
        @click="submit"
        v-if="!companyInfo || companyInfo.status != 1"
        >确 定</el-button
      >
    </div>
  </el-dialog>
</template>
  <script>
import { applyCompany, getCompanyInfo } from '@/api/user'
const defaultForm = {
  name: '',
  code: '',
  logo: '',
  logoFull: '',
  license: '',
  licenseFull: '',
  contactName: '',
  contactMobile: '',
  contactEmail: '',
}
export default {
  name: 'ApplyCompanyForm',
  components: {
    VrUpload: () => import('@/components/VrUpload.vue'),
  },
  props: {},
  data() {
    return {
      vipInfo: null,
      companyInfo: null,
      dialogFormVisible: false,
      formLabelWidth: '140px',
      submitLoading: false,
      form: Object.assign({}, defaultForm),
      rules: {
        name: [{ required: true, message: '请输入企业名称', trigger: 'blur' }],
        code: [{ required: true, message: '请输入信用代码', trigger: 'blur' }],
        contactName: [
          { required: true, message: '请输入联系人', trigger: 'blur' },
        ],
        contactMobile: [
          {
            required: true,
            validator: (rule, value, callback) => {
              const phoneRegex = /^1[3-9]\d{9}$/
              if (!value) {
                callback(new Error('请输入手机号'))
              } else if (!phoneRegex.test(value)) {
                callback(new Error('请输入有效的手机号'))
              } else {
                callback()
              }
            },
            trigger: 'blur',
          },
        ],
        contactEmail: [
          {
            type: 'email',
            message: '请输入正确的邮箱号',
            trigger: 'blur',
          },
        ],
      },
    }
  },
  methods: {
    async open(vipInfo) {
      this.dialogFormVisible = true
      this.vipInfo = vipInfo
      await this.getCompanyInfo()
    },
    async getCompanyInfo() {
      this.companyInfo = await getCompanyInfo(this.vipInfo.id)
      if (this.companyInfo) {
        this.form = {
          name: this.companyInfo.name,
          code: this.companyInfo.code,
          logo: this.companyInfo.logo,
          logoFull: this.companyInfo.logoFull,
          license: this.companyInfo.license,
          licenseFull: this.companyInfo.licenseFull,
          contactName: this.companyInfo.contactName,
          contactMobile: this.companyInfo.contactMobile,
          contactEmail: this.companyInfo.contactEmail,
        }
        this.$refs.logoUpload.initFileList([
          {
            name: this.form.name,
            url: this.form.logoFull,
            path: this.form.logo,
          },
        ])
        this.$refs.licenseUpload.initFileList([
          {
            name: this.form.name,
            url: this.form.licenseFull,
            path: this.form.license,
          },
        ])
      } else {
        this.form = Object.assign(defaultForm, {})
      }
      this.$nextTick(() => {
        this.$refs.companyForm.clearValidate()
      })
    },
    // 上传成功
    onLicenseUploadSuccess(data) {
      this.form.license = data.path
    },
    onLogoUploadSuccess(data) {
      this.form.logo = data.path
    },
    cancel() {
      this.form = Object.assign({}, defaultForm)
      this.$refs.companyForm.resetFields()
      this.$refs.companyForm.clearValidate()
      this.dialogFormVisible = false
    },
    submit() {
      this.submitLoading = true
      this.$refs.companyForm.validate((valid, errs) => {
        if (valid) {
          applyCompany(this.form)
            .then(() => {
              this.$message.success('提交成功')
              this.cancel()
              this.$emit('ok')
            })
            // eslint-disable-next-line no-unused-vars
            .catch((_err) => {
              setTimeout(() => {
                this.submitLoading = false
              }, 1000)
              // this.$message.error(_err.message)
            })
        } else {
          setTimeout(() => {
            this.submitLoading = false
          }, 1500)
          for (const key in errs) {
            this.$message.error(errs[key][0].message)
            return false
          }
        }
      })
    },
  },
}
</script>
